<script setup lang="ts">
import {computed,onBeforeUnmount,onMounted,ref,watch} from 'vue'
import {WorkflowCommandError} from './workflow-operation'
import type {WorkflowArtLinkInput,WorkflowArtLinks,WorkflowArtNeeds,WorkflowOperationProvider,WorkflowOperationRecord,WorkflowPlanTask} from './workflow-operation'
const props=defineProps<{provider:WorkflowOperationProvider;record:WorkflowOperationRecord;task:WorkflowPlanTask;projects:{id:string;name:string}[];storage:Pick<Storage,'getItem'|'setItem'|'removeItem'>|null;blocked:boolean}>()
const emit=defineEmits<{(e:'changed'):void}>()
const project=ref(props.record.projectId??''),domain=ref<'shared'|'ant'|'cook'>('shared'),catalogue=ref<WorkflowArtNeeds|null>(null),links=ref<WorkflowArtLinks|null>(null),needId=ref(''),pending=ref<WorkflowArtLinkInput|null>(null),busy=ref(false),error=ref(''),corrupt=ref(false)
let alive=true,generation=0
watch(()=>[props.record.id,props.record.revision,props.record.plan?.digest,props.task.taskId],()=>{generation++},{flush:'sync'})
const current=(ticket:number)=>alive&&generation===ticket
const boundId=props.record.id,boundPlan=props.record.plan?.digest,boundTask=props.task.taskId
const scopeCurrent=()=>props.record.id===boundId&&props.record.plan?.digest===boundPlan&&props.task.taskId===boundTask
const key=`companion.workflow-art-link.v1.${boundId}`
watch(()=>props.record.revision,()=>{links.value=null;catalogue.value=null;needId.value=''},{flush:'sync'})
const selected=computed(()=>catalogue.value?.needs.find(n=>n.needId===needId.value))
const currentLinks=computed(()=>links.value?.links.filter(l=>l.taskId===props.task.taskId)??[])
function persist(value:WorkflowArtLinkInput|null){if(!props.storage)throw Error();if(value){const json=JSON.stringify(value);props.storage.setItem(key,json);if(props.storage.getItem(key)!==json)throw Error()}else{props.storage.removeItem(key);if(props.storage.getItem(key)!==null)throw Error()}pending.value=value}
function restore(){try{if(!props.storage)throw Error();const raw=props.storage.getItem(key);if(!raw)return;const p=JSON.parse(raw);if(!p||typeof p.operationId!=='string'||typeof p.taskId!=='string'||typeof p.planDigest!=='string'||!Number.isSafeInteger(p.expectedRevision)||typeof p.artProjectId!=='string'||typeof p.needId!=='string'||typeof p.needDigest!=='string'||typeof p.workbenchHash!=='string'||![null,'ant','cook'].includes(p.resourceDomainId))throw Error();pending.value=p}catch{corrupt.value=true;error.value='关联请求记录不可读，操作已锁定。'}}
restore()
async function readLinks(){if(!scopeCurrent()||busy.value||!props.provider.readArtLinks)return;busy.value=true;error.value='';const ticket=generation;try{const value=await props.provider.readArtLinks(props.record.id);if(!current(ticket))return;if(value.workflowId!==props.record.id)throw Error();links.value=value}catch{if(current(ticket)){links.value=null;error.value='美术关联读取失败或服务未接入；状态待核对。'}}finally{if(alive)busy.value=false}}
async function readNeeds(){if(!scopeCurrent()||busy.value||!props.provider.readArtNeeds||!project.value)return;busy.value=true;error.value='';catalogue.value=null;needId.value='';const id=project.value,selectedDomain=domain.value,ticket=generation;try{const value=await props.provider.readArtNeeds(props.record.id,id,selectedDomain);if(!current(ticket))return;if(project.value!==id||domain.value!==selectedDomain||value.workflowId!==props.record.id||value.projectId!==id||value.resourceDomainId!==(selectedDomain==='shared'?null:selectedDomain))throw Error();catalogue.value=value}catch{if(current(ticket))error.value='美术需求读取失败或来源不可用，无法关联。'}finally{if(alive)busy.value=false}}
async function attach(){const need=selected.value,c=catalogue.value,l=links.value,digest=props.record.plan?.digest,ticket=generation;if(!scopeCurrent()||busy.value||pending.value||corrupt.value||props.blocked||!need||!c?.workbenchHash||!l||!digest||!props.provider.createArtLink)return;const p:WorkflowArtLinkInput={operationId:crypto.randomUUID(),expectedRevision:l.revision,planDigest:digest,taskId:props.task.taskId,artProjectId:c.projectId,resourceDomainId:c.resourceDomainId,needId:need.needId,workbenchHash:c.workbenchHash,needDigest:need.needDigest};try{persist(p)}catch{corrupt.value=true;error.value='无法保存原请求，未提交。';return}busy.value=true;error.value='';try{const result=await props.provider.createArtLink(props.record.id,p);if(!current(ticket))return;if(result.workflowId!==props.record.id||result.revision<=p.expectedRevision||!result.links.some(x=>x.planDigest===p.planDigest&&x.taskId===p.taskId&&x.artProjectId===p.artProjectId&&x.resourceDomainId===p.resourceDomainId&&x.needId===p.needId&&x.workbenchHash===p.workbenchHash&&x.needDigest===p.needDigest))throw Error();persist(null);links.value=result;emit('changed');error.value='关联已保存；美术任务状态仍需单独核对。'}catch(e){if(!current(ticket))return;if(e instanceof WorkflowCommandError&&e.outcome==='rejected'){try{persist(null)}catch{corrupt.value=true}error.value='关联被拒绝，请重新读取需求与当前关联。'}else error.value='关联结果待核对；保留原请求，不自动重发。'}finally{if(alive)busy.value=false}}
async function reconcile(){const p=pending.value;if(!scopeCurrent()||!p||busy.value||!props.provider.readArtLinks)return;busy.value=true;const ticket=generation;try{const result=await props.provider.getOperation(p.operationId,props.record.id);if(!current(ticket))return;if(result.operationId!==p.operationId||result.workflowId!==props.record.id)throw Error();if(result.state==='rejected'&&result.outcome==='not-applied'&&result.code==='MANAGEMENT_NOT_APPLIED_RECORD_CHANGED'){persist(null);error.value='原关联未应用，请读取最新关联及需求后重新确认。';return}if(result.state!=='settled')throw Error();const resultLinks=await props.provider.readArtLinks(props.record.id);if(!current(ticket))return;if(resultLinks.workflowId!==props.record.id||resultLinks.revision<=p.expectedRevision)throw Error();persist(null);links.value=resultLinks;emit('changed');error.value='已核对原关联请求；当前关联可能已更新。'}catch{if(current(ticket))error.value='原关联结果待核对，不自动重发。'}finally{if(alive)busy.value=false}}
async function continueOriginal(){const p=pending.value;if(!scopeCurrent()||!p||busy.value||!props.provider.createArtLink)return;busy.value=true;const ticket=generation;try{const result=await props.provider.createArtLink(props.record.id,p);if(!current(ticket))return;if(result.workflowId!==props.record.id||result.revision<=p.expectedRevision||!result.links.some(x=>x.planDigest===p.planDigest&&x.taskId===p.taskId&&x.artProjectId===p.artProjectId&&x.resourceDomainId===p.resourceDomainId&&x.needId===p.needId&&x.workbenchHash===p.workbenchHash&&x.needDigest===p.needDigest))throw Error();persist(null);links.value=result;emit('changed');error.value='原关联请求已完成。'}catch(e){if(!current(ticket))return;if(e instanceof WorkflowCommandError&&e.outcome==='rejected'&&e.code==='MANAGEMENT_NOT_APPLIED_RECORD_CHANGED'){try{persist(null);error.value='原关联未应用，请读取最新关联及需求后重新确认。'}catch{corrupt.value=true;error.value='请求记录不可用，保持锁定。'}}else error.value='原关联结果待核对，保留原请求。'}finally{if(alive)busy.value=false}}
let timer:ReturnType<typeof setInterval>|undefined
onMounted(()=>{void readLinks();timer=setInterval(()=>{if(pending.value&&!busy.value)void reconcile()},15000)})
onBeforeUnmount(()=>{alive=false;generation++;if(timer)clearInterval(timer)})
</script>
<template><section aria-label="美术需求关联"><h4>美术需求关联</h4><p>只关联已有需求，不会创建或启动美术生成。</p><p v-if="error" role="status">{{ error }}</p><p v-if="pending">关联请求待核对。<button type="button" :disabled="busy" @click="reconcile">查询原请求</button><button type="button" :disabled="busy||!provider.createArtLink" @click="continueOriginal">继续原关联请求</button></p><p v-if="!links">关联状态尚未读取或服务不可用。<button type="button" :disabled="busy||!provider.readArtLinks" @click="readLinks">读取关联状态</button></p><p v-else-if="!currentLinks.length">当前任务未关联美术需求。</p><ul v-else><li v-for="l in currentLinks" :key="l.planDigest+':'+l.artProjectId+':'+l.needId">{{ projects.find(p=>p.id===l.artProjectId)?.name||'工程名称未提供' }} / {{ l.needName||'需求名称未读取' }} · {{ l.planDigest!==record.plan?.digest?'旧计划绑定，待核对':l.state==='current'?'关联有效（需求状态未核验）':l.state==='stale'?'需求已变化，待核对':'来源不可用，待核对' }}<details><summary>关联技术信息</summary>工程 {{ l.artProjectId }} · 需求 {{ l.needId }}</details></li></ul><details><summary>关联已有美术需求</summary><label>美术工程<select v-model="project" @change="catalogue=null;needId='' "><option value="">选择已登记工程</option><option v-for="p in projects" :key="p.id" :value="p.id">{{ p.name }}</option></select></label><label>资源域<select v-model="domain" @change="catalogue=null;needId='' "><option value="shared">共享</option><option value="ant">蚂蚁</option><option value="cook">厨师</option></select></label><button type="button" :disabled="busy||!project||!provider.readArtNeeds" @click="readNeeds">读取已有需求</button><p v-if="catalogue&&!catalogue.needs.length">该来源未提供需求。</p><label v-if="catalogue?.needs.length">选择需求<select v-model="needId"><option value="">请选择</option><option v-for="n in catalogue.needs" :key="n.needId" :value="n.needId">{{ n.name }}</option></select></label><button type="button" :disabled="busy||!!pending||corrupt||blocked||!selected||!catalogue?.workbenchHash||!links||!provider.createArtLink" @click="attach">确认关联</button></details></section></template>
